+    }
+  });
+
+  afterEach(async () => {
+    for (const dir of [testDir, remoteDir]) {
+      try { await fs.rm(dir, { recursive: true, force: true }); } catch { /* noop */ }
+    }
+  });
+
+  async function setupSyncTest(): Promise<string> {
+    // Create bare remote
+    execSync('git init --bare', { cwd: remoteDir, stdio: 'pipe' });
+
